def find_combinations(test_list):
    combinations = []
    n = len(test_list)

    for i in range(n):
        for j in range(n):
            if i != j:
                # Select first element from first tuple and second from second tuple
                combinations.append((test_list[i][0] + test_list[j][0], test_list[i][1] + test_list[j][1]))

    # Remove duplicates while preserving order (Python 3.7+ maintains insertion order for dictionaries)
    seen = set()
    unique_combinations = []
    for combo in combinations:
        if combo not in seen:
            seen.add(combo)
            unique_combinations.append(combo)

    return unique_combinations
