def left_rotate(n, d):
    if d == 0:
        return n
    # Ensure d is within the range of 0-31 for 32-bit numbers
    d = d % 32
    # Perform the rotation: shift left by d bits and OR with the shifted right by (32 - d) bits
    return (n << d) | (n >> (32 - d))
